<script setup>
import { computed, onMounted, ref } from 'vue'
import { getCourierParcels } from '../../api/parcels'
import { normalizeApiError } from '../../utils/apiError'
import { formatDateTime, formatRelativeExpiry } from '../../utils/format'
import PageHeader from '../../components/PageHeader.vue'
import LoadingState from '../../components/LoadingState.vue'
import ErrorState from '../../components/ErrorState.vue'
import EmptyState from '../../components/EmptyState.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import AppIcon from '../../components/AppIcon.vue'
import { sizeText } from '../../utils/displayText'

const parcels=ref([]);const loading=ref(true);const refreshing=ref(false);const errorMessage=ref('');const filter=ref('ALL')
const filtered=computed(()=>filter.value==='ALL'?parcels.value:parcels.value.filter(p=>p.status===filter.value))
async function load(refresh=false){refresh?(refreshing.value=true):(loading.value=true);errorMessage.value='';try{parcels.value=await getCourierParcels()}catch(error){errorMessage.value=normalizeApiError(error,'包裹数据加载失败').message}finally{loading.value=false;refreshing.value=false}}
onMounted(()=>load())
</script>

<template><section><PageHeader title="我的包裹" eyebrow="快递员" description="这里只展示分配给当前登录快递员的包裹。"><button class="btn-secondary" type="button" :disabled="refreshing" @click="load(true)"><AppIcon name="refresh" :size="16"/>{{refreshing?'正在刷新...':'刷新'}}</button></PageHeader><div class="panel mt-6 flex flex-wrap items-end gap-3 p-4"><label class="form-field w-52"><span>状态筛选</span><select v-model="filter"><option value="ALL">全部状态</option><option value="CREATED">已创建</option><option value="STORED">待取件</option><option value="PICKED_UP">已取件</option><option value="EXPIRED">已过期</option><option value="CANCELLED">已取消</option></select></label><p class="ml-auto self-center text-xs font-semibold text-[var(--color-ink-500)]">显示 {{filtered.length}} / {{parcels.length}} 个包裹</p></div><LoadingState v-if="loading" class="mt-6" message="正在加载包裹..."/><ErrorState v-else-if="errorMessage" class="mt-6" :message="errorMessage" @retry="load()"/><EmptyState v-else-if="!filtered.length" class="mt-6" message="没有符合当前筛选条件的包裹。"/><template v-else><div class="panel responsive-table mt-6 hidden max-h-[42rem] overflow-auto md:block"><table class="w-full min-w-[900px] text-left text-sm"><thead class="border-b border-[var(--color-line)] bg-[var(--color-surface)] text-[10px] uppercase tracking-[.08em] text-[var(--color-ink-500)]"><tr><th class="p-4">快递单号</th><th class="p-4">状态</th><th class="p-4">尺寸</th><th class="p-4">用户</th><th class="p-4">站点／柜格</th><th class="p-4">入柜时间</th><th class="p-4">取件截止时间</th><th class="p-4">取件时间</th></tr></thead><tbody><tr v-for="parcel in filtered" :key="parcel.id" class="border-b border-[var(--color-line)] last:border-0"><td class="tracking-code p-4">{{parcel.trackingNumber}}</td><td class="p-4"><StatusBadge :status="parcel.status"/></td><td class="p-4 font-semibold">{{sizeText(parcel.size)}}</td><td class="p-4">#{{parcel.customerId}}</td><td class="p-4">{{parcel.stationName||'—'}}<br/><span class="text-xs font-bold text-[var(--color-brand-deep)]">柜格 {{parcel.lockerCellCode||'—'}}</span></td><td class="p-4">{{formatDateTime(parcel.storedAt)}}</td><td class="p-4">{{formatDateTime(parcel.expiresAt)}}<span v-if="parcel.status==='STORED'" class="expiry-relative mt-1 block">{{formatRelativeExpiry(parcel.expiresAt)}}</span></td><td class="p-4">{{formatDateTime(parcel.pickedUpAt)}}</td></tr></tbody></table></div><div class="mt-6 grid gap-4 md:hidden"><article v-for="parcel in filtered" :key="parcel.id" class="panel parcel-card"><div class="parcel-accent" :class="`parcel-accent-${parcel.status.toLowerCase()}`"></div><div class="p-5"><div class="flex items-start justify-between gap-3"><p class="tracking-code">{{parcel.trackingNumber}}</p><StatusBadge :status="parcel.status"/></div><dl class="mt-5 grid grid-cols-2 gap-4 text-sm"><div><dt>站点</dt><dd>{{parcel.stationName||'—'}}</dd></div><div><dt>柜格</dt><dd>{{parcel.lockerCellCode||'—'}}</dd></div><div><dt>尺寸</dt><dd>{{sizeText(parcel.size)}}</dd></div><div><dt>用户</dt><dd>#{{parcel.customerId}}</dd></div><div class="col-span-2"><dt>取件截止时间</dt><dd>{{formatDateTime(parcel.expiresAt)}}</dd><p v-if="parcel.status==='STORED'" class="expiry-relative mt-1">{{formatRelativeExpiry(parcel.expiresAt)}}</p></div></dl></div></article></div></template></section></template>
